"""Byte-sequence API for the compressed payload extension.

Compressed byte sequences support concatenation, repetition and byte slices
without materializing expanded content.  Fingerprints and bounded window
access work directly over the compressed representation, so captures and
receipts may cover very large logical objects.
"""
import ast
import hashlib
import keyword
import re

MAX = (1 << 63) - 1
_MASK = (1 << 64) - 1
BASE = 257

MAX_DEPTH = 128
EXPRESSION_LIMIT = 8192
TEMPLATE_LIMIT = 65536
_NAME = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z')
_MARKER = '<<random_string>>'


def _hash(data):
    """sum((b[i]+1)*257^(N-1-i)) modulo 2^64."""
    h = 0
    for b in data:
        h = (h * BASE + b + 1) & _MASK
    return h


def _combine(n1, h1, n2, h2):
    if n2 == 0:
        return n1, h1
    if n1 == 0:
        return n2, h2
    return n1 + n2, (h1 * pow(BASE, n2, 1 << 64) + h2) & _MASK


class Seq:
    """A logical byte sequence."""
    __slots__ = ('n',)

    def size(self):
        return self.n

    def fp(self):
        return self.fp_range(0, self.n)

    def fp_range(self, lo, hi):
        raise NotImplementedError

    def window(self, lo, hi):
        raise NotImplementedError


class Lit(Seq):
    __slots__ = ('data', '_fp')

    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self._fp = _hash(data)

    def fp_range(self, lo, hi):
        if hi <= lo:
            return 0, 0
        if lo <= 0 and hi >= self.n:
            return self.n, self._fp
        return hi - lo, _hash(self.data[lo:hi])

    def window(self, lo, hi):
        return self.data[lo:hi]


class Cat(Seq):
    __slots__ = ('parts',)

    def __init__(self, parts):
        self.parts = parts
        self.n = 0
        for p in parts:
            self.n += p.n

    def fp_range(self, lo, hi):
        if hi <= lo:
            return 0, 0
        n = 0
        h = 0
        off = 0
        for p in self.parts:
            p0 = off
            p1 = off + p.n
            off = p1
            if hi <= p0:
                break
            if lo >= p1:
                continue
            a = max(lo, p0) - p0
            b = min(hi, p1) - p0
            pn, ph = p.fp_range(a, b)
            n, h = _combine(n, h, pn, ph)
        return n, h

    def window(self, lo, hi):
        out = bytearray()
        off = 0
        for p in self.parts:
            p0 = off
            p1 = off + p.n
            off = p1
            if hi <= p0:
                break
            if lo >= p1:
                continue
            a = max(lo, p0) - p0
            b = min(hi, p1) - p0
            out += p.window(a, b)
        return bytes(out)


class Rep(Seq):
    __slots__ = ('unit', 'count', '_table')

    def __init__(self, unit, count):
        self.unit = unit
        self.count = count
        self.n = unit.n * count
        table = [unit.fp()]
        k = 1
        while (1 << k) <= count:
            hp, lp = table[-1]
            hn, ln = _combine(lp, hp, lp, hp)
            table.append((hn, ln))
            k += 1
        self._table = table

    def _unit_pow(self, m):
        n = 0
        h = 0
        k = 0
        while m:
            if m & 1:
                hk, lk = self._table[k]
                n, h = _combine(n, h, lk, hk)
            m >>= 1
            k += 1
        return n, h

    def fp_range(self, lo, hi):
        if hi <= lo:
            return 0, 0
        L = self.unit.n
        n = 0
        h = 0
        x = lo
        while x < hi:
            o = x % L
            if o == 0:
                m = (hi - x) // L
                if m:
                    pn, ph = self._unit_pow(m)
                    n, h = _combine(n, h, pn, ph)
                    x += m * L
                    continue
            take = min(L - o, hi - x)
            pn, ph = self.unit.fp_range(o, o + take)
            n, h = _combine(n, h, pn, ph)
            x += take
        return n, h

    def window(self, lo, hi):
        L = self.unit.n
        out = bytearray()
        x = lo
        while x < hi:
            o = x % L
            if o == 0:
                m = (hi - x) // L
                if m:
                    out += self.unit.window(0, L) * m
                    x += m * L
                    continue
            take = min(L - o, hi - x)
            out += self.unit.window(o, o + take)
            x += take
        return bytes(out)


_EMPTY = Lit(b'')


def literal(data):
    if data is None:
        return _EMPTY
    if type(data) is not bytes:
        raise ValueError('literal bytes')
    return Lit(data) if data else _EMPTY


def size(node):
    return node.n if node is not None else 0


def _cat_many(parts):
    good = [p for p in parts if p.n]
    if not good:
        return _EMPTY
    if len(good) == 1:
        return good[0]
    return Cat(good)


def concat(a, b):
    if a is None or a.n == 0:
        return b if b is not None else _EMPTY
    if b is None or b.n == 0:
        return a
    parts = []
    if isinstance(a, Cat):
        parts.extend(a.parts)
    else:
        parts.append(a)
    if isinstance(b, Cat):
        parts.extend(b.parts)
    else:
        parts.append(b)
    return Cat(parts)


def repeat(node, count):
    if node is None:
        node = _EMPTY
    if type(count) is not int or isinstance(count, bool) or count < 0:
        raise ValueError('repeat count')
    if count == 0 or node.n == 0:
        return _EMPTY
    if isinstance(node, Rep):
        unit = node.unit
        total = node.count * count
    else:
        unit = node
        total = count
    if unit.n * total > MAX:
        raise ValueError('sequence length')
    return Rep(unit, total)


def cut(node, lo, hi):
    if node is None:
        node = _EMPTY
    if type(lo) is not int or type(hi) is not int:
        raise ValueError('slice bounds')
    if not 0 <= lo <= hi <= node.n:
        raise ValueError('slice bounds')
    if lo == 0 and hi == node.n:
        return node
    if lo == hi:
        return _EMPTY
    if isinstance(node, Lit):
        return Lit(node.data[lo:hi])
    if isinstance(node, Cat):
        parts = []
        off = 0
        for p in node.parts:
            p0 = off
            p1 = off + p.n
            off = p1
            if hi <= p0:
                break
            if lo >= p1:
                continue
            piece = cut(p, max(lo, p0) - p0, min(hi, p1) - p0)
            if piece.n:
                parts.append(piece)
        return _cat_many(parts)
    L = node.unit.n
    parts = []
    x = lo
    while x < hi:
        o = x % L
        if o == 0:
            m = (hi - x) // L
            if m:
                parts.append(Rep(node.unit, m))
                x += m * L
                continue
        take = min(L - o, hi - x)
        piece = cut(node.unit, o, o + take)
        if piece.n:
            parts.append(piece)
        x += take
    return _cat_many(parts)


def materialize(node, limit=65536):
    if node is None:
        return b''
    if node.n > limit:
        raise ValueError('bounded materialization')
    return node.window(0, node.n)


def fingerprint(node):
    if node is None:
        n, h = 0, 0
    else:
        n, h = node.fp()
    return {'n': n, 'h': format(h, '016x')}


def fp_bytes(data):
    return {'n': len(data), 'h': format(_hash(data), '016x')}


def next_lf(node, start=0, window=8194):
    """Index of the first LF at or after start within the window, else -1."""
    if node is None:
        return -1
    end = min(start + window, node.n)
    pos = start
    while pos < end:
        chunk = node.window(pos, min(pos + 4096, end))
        k = chunk.find(b'\n')
        if k >= 0:
            return pos + k
        pos += len(chunk)
    return -1


# ---------------------------------------------------------------------------
# Expression evaluation and templates


class Context:
    def __init__(self, definitions, seed):
        self.seed = seed
        self.env = {}
        seen = set()
        for row in definitions:
            name, src = row
            if type(name) is not str or not _NAME.fullmatch(name) or keyword.iskeyword(name):
                raise ValueError('definition name')
            if name in seen:
                raise ValueError('definition name')
            seen.add(name)
            if type(src) is not str or len(src) > EXPRESSION_LIMIT:
                raise ValueError('expression source')
            self.env[name] = self.expression(src)

    # -- expressions -------------------------------------------------------
    def expression(self, text):
        try:
            tree = ast.parse(text, mode='eval')
        except SyntaxError:
            raise ValueError('expression syntax') from None
        body = tree.body
        self._check_depth(body)
        value = self._eval(body)
        if not isinstance(value, Seq):
            raise ValueError('expression result')
        return value

    @staticmethod
    def _check_depth(root):
        stack = [(root, 0)]
        while stack:
            node, depth = stack.pop()
            if depth > MAX_DEPTH:
                raise ValueError('expression depth')
            for child in ast.iter_child_nodes(node):
                stack.append((child, depth + 1))

    def _eval(self, node):
        if isinstance(node, ast.Constant):
            v = node.value
            if type(v) is str:
                return Lit(v.encode('utf8'))
            if type(v) is bytes:
                return Lit(v) if v else _EMPTY
            if type(v) is int:
                if 0 <= v <= MAX:
                    return v
                raise ValueError('integer literal')
            raise ValueError('constant type')
        if isinstance(node, ast.Name):
            if node.id in self.env:
                return self.env[node.id]
            raise ValueError('unknown name')
        if isinstance(node, ast.BinOp):
            if isinstance(node.op, ast.Add):
                a = self._eval(node.left)
                b = self._eval(node.right)
                if isinstance(a, Seq) and isinstance(b, Seq):
                    return concat(a, b)
                raise ValueError('concatenation types')
            if isinstance(node.op, ast.Mult):
                a = self._eval(node.left)
                b = self._eval(node.right)
                if isinstance(a, Seq) and type(b) is int:
                    return repeat(a, b)
                if type(a) is int and isinstance(b, Seq):
                    return repeat(b, a)
                raise ValueError('repetition types')
            raise ValueError('operator')
        if isinstance(node, ast.Subscript):
            value = self._eval(node.value)
            if not isinstance(value, Seq):
                raise ValueError('slice target')
            sl = node.slice
            if not isinstance(sl, ast.Slice):
                raise ValueError('index')
            if sl.step is not None:
                if not (isinstance(sl.step, ast.Constant) and sl.step.value is None):
                    raise ValueError('slice step')
            lo = self._bound(sl.lower, 0)
            hi = self._bound(sl.upper, value.n)
            if not 0 <= lo <= hi <= value.n:
                raise ValueError('slice bounds')
            return cut(value, lo, hi)
        raise ValueError('unsupported syntax')

    @staticmethod
    def _bound(node, default):
        if node is None:
            return default
        if isinstance(node, ast.Constant) and type(node.value) is int:
            return node.value
        raise ValueError('slice endpoint')

    # -- templates ---------------------------------------------------------
    def template(self, value, coordinate):
        if type(value) is not str:
            raise ValueError('template type')
        if len(value) >= 4 and value.startswith('{{') and value.endswith('}}'):
            src = value[2:-2].strip()
            if len(src) > EXPRESSION_LIMIT:
                raise ValueError('expression source')
            return self.expression(src)
        if len(value) > TEMPLATE_LIMIT:
            raise ValueError('template source')
        if _MARKER not in value:
            return Lit(value.encode('utf8')) if value else _EMPTY
        out = []
        rest = value
        occurrence = 0
        while True:
            k = rest.find(_MARKER)
            if k < 0:
                out.append(rest)
                break
            out.append(rest[:k])
            out.append(self._random(coordinate, occurrence))
            occurrence += 1
            rest = rest[k + len(_MARKER):]
        return Lit(''.join(out).encode('utf8'))

    def _random(self, coordinate, occurrence):
        source = f'{self.seed}/{coordinate}/{occurrence}'.encode('utf8')
        return hashlib.sha256(source).hexdigest()[:20]
